DO $do$ DECLARE r public.ao_library_cards; s jsonb := $t${"title": "Review repair estimates and approve material work", "what_text": "Review a specific repair or improvement recommendation, compare the quoted scope and cost with the property need, and provide an approval or decision when required.\n\nWhy it matters: Material repairs need a clear homeowner decision under the agreement. A timely, specific answer keeps the home guest-ready.\n\nSteps:\n1. Review the issue description, photos, recommended scope, quote and timing.\n2. Ask questions about guest impact, alternatives, warranty and what is excluded.\n3. Confirm whether the work is repair, replacement or optional upgrade.\n4. Approve, decline or request a revised bid in writing.\n5. Do not direct a vendor independently unless ARHA has agreed to coordinate the change.\n\nWhat to submit: Decision on the estimate. Answer fields: Decision, notes.\n\nWhat to keep: Retain the reviewed record, the homeowner's questions or analysis and the final written decision.\n\nRecord only the time you personally spend on this card. Do not include time spent by ARHA, a vendor or another household member.", "why_text": "Material repairs need a clear homeowner decision under the agreement. A timely, specific answer keeps the home guest-ready.", "how_text": "1. Review the issue description, photos, recommended scope, quote and timing.\n2. Ask questions about guest impact, alternatives, warranty and what is excluded.\n3. Confirm whether the work is repair, replacement or optional upgrade.\n4. Approve, decline or request a revised bid in writing.\n5. Do not direct a vendor independently unless ARHA has agreed to coordinate the change.", "required_output": "Decision on the estimate", "documentation_note": "Evidence to keep: Retain the reviewed record, the homeowner's questions or analysis and the final written decision. Time: the homeowner enters actual minutes after doing the work; no estimated or prefilled time. Attestation: the homeowner confirms the entry reflects their own time and work for this home.", "lane": "triggered", "stage_window": "operations", "team_needs_this": true, "lock_rule": "until_linked_step_done", "linked_template_task_ids": [], "opens_text": "Locked until ARHA issues an estimate", "output_fields": [{"key": "decision", "label": "Decision", "type": "text"}, {"key": "notes", "label": "Notes", "type": "text"}], "status": "released", "retired_at": null}$t$::jsonb; BEGIN
  SELECT * INTO r FROM public.ao_library_cards WHERE code = 'A15' FOR UPDATE;
  r := jsonb_populate_record(r, s);
  UPDATE public.ao_library_cards SET title=r.title, what_text=r.what_text, why_text=r.why_text, how_text=r.how_text, required_output=r.required_output,
    documentation_note=r.documentation_note, lane=r.lane, stage_window=r.stage_window, team_needs_this=r.team_needs_this, lock_rule=r.lock_rule,
    linked_template_task_ids=r.linked_template_task_ids, opens_text=r.opens_text, output_fields=r.output_fields, status=r.status, retired_at=r.retired_at,
    version = version + 1, updated_by = '98bd6696-4018-4965-b645-0471c5ae3925', updated_at = now() WHERE code = 'A15' RETURNING * INTO r;
  INSERT INTO public.ao_library_card_history(card_id, version, snapshot, changed_by) VALUES (r.id, r.version, to_jsonb(r), '98bd6696-4018-4965-b645-0471c5ae3925');
END $do$;
DO $do$ DECLARE r public.ao_library_cards; s jsonb := $t${"title": "Review the floor plan", "what_text": "ARHA or its design partner prepares the plan from available measurements and site information. It is a setup and furnishing reference; the homeowner's remote review does not replace ARHA's onsite measurement or safety check.\n\nWhy it matters: Furniture placement decides how comfortable and functional the home feels. Catching layout issues on paper saves returns and rework.\n\nSteps:\n1. Open the floor plan ARHA uploaded and review each room's furniture placement.\n2. Check guest flow: clear walkways, bed access from both sides where possible, a usable workspace and seating for the stated occupancy.\n3. Flag any known measurement, door swing, outlet, window or fixture detail that may affect placement.\n4. Mark the plan Approve or Comment, and tie each comment to a specific room and item.\n5. Submit one consolidated response. ARHA verifies measurements and safety onsite before execution.\n\nWhat to submit: Floor plan response. Answer fields: Approve or comment, notes.\n\nWhat to keep: Retain the completed worksheet or draft, source links and any supporting screenshots used to prepare it.\n\nRecord only the time you personally spend on this card. Do not include time spent by ARHA, a vendor or another household member.", "why_text": "Furniture placement decides how comfortable and functional the home feels. Catching layout issues on paper saves returns and rework.", "how_text": "1. Open the floor plan ARHA uploaded and review each room's furniture placement.\n2. Check guest flow: clear walkways, bed access from both sides where possible, a usable workspace and seating for the stated occupancy.\n3. Flag any known measurement, door swing, outlet, window or fixture detail that may affect placement.\n4. Mark the plan Approve or Comment, and tie each comment to a specific room and item.\n5. Submit one consolidated response. ARHA verifies measurements and safety onsite before execution.", "required_output": "Floor plan response", "documentation_note": "Evidence to keep: Retain the completed worksheet or draft, source links and any supporting screenshots used to prepare it. Time: the homeowner enters actual minutes after doing the work; no estimated or prefilled time. Attestation: the homeowner confirms the entry reflects their own time and work for this home.", "lane": "critical", "stage_window": "onboarding_early", "team_needs_this": true, "lock_rule": "until_linked_step_done", "linked_template_task_ids": ["465ed7be-2ae9-497f-857f-447553df16c5"], "opens_text": "Locked until ARHA uploads the floor plan", "output_fields": [{"key": "approve_or_comment", "label": "Approve or comment", "type": "text"}, {"key": "notes", "label": "Notes", "type": "text"}], "status": "released", "retired_at": null}$t$::jsonb; BEGIN
  SELECT * INTO r FROM public.ao_library_cards WHERE code = 'A26' FOR UPDATE;
  r := jsonb_populate_record(r, s);
  UPDATE public.ao_library_cards SET title=r.title, what_text=r.what_text, why_text=r.why_text, how_text=r.how_text, required_output=r.required_output,
    documentation_note=r.documentation_note, lane=r.lane, stage_window=r.stage_window, team_needs_this=r.team_needs_this, lock_rule=r.lock_rule,
    linked_template_task_ids=r.linked_template_task_ids, opens_text=r.opens_text, output_fields=r.output_fields, status=r.status, retired_at=r.retired_at,
    version = version + 1, updated_by = '98bd6696-4018-4965-b645-0471c5ae3925', updated_at = now() WHERE code = 'A26' RETURNING * INTO r;
  INSERT INTO public.ao_library_card_history(card_id, version, snapshot, changed_by) VALUES (r.id, r.version, to_jsonb(r), '98bd6696-4018-4965-b645-0471c5ae3925');
END $do$;
DO $do$ DECLARE r public.ao_library_cards; s jsonb := $t${"title": "Attend the handoff meeting and review what carries into go-live", "what_text": "ARHA uses the handoff to explain the home's operating information, open items and communication paths. The homeowner confirms their understanding and raises any unresolved questions; ARHA assigns internal follow-up.\n\nWhy it matters: The handoff sets how the home runs after launch. Clear authority and open items now prevent confusion once guests arrive.\n\nSteps:\n1. Before the meeting, review the handoff packet ARHA shares, including open items, guest instructions and communication paths.\n2. Write down questions about anything that is unclear or that you expected to be different.\n3. Attend the meeting, confirm the operating authority and approval thresholds that apply after go-live, and ask your questions.\n4. Give any correction or direction on items that need a homeowner decision.\n5. Within the deadline, record your takeaways, questions, decisions and the open items carrying into go-live.\n\nWhat to submit: Meeting notes and takeaways (includes ready-for-booking notice and carry-over items). Answer fields: Takeaways, questions.\n\nWhat to keep: Retain the reviewed record, the homeowner's questions or analysis and the final written decision.\n\nRecord only the time you personally spend on this card. Do not include time spent by ARHA, a vendor or another household member.", "why_text": "The handoff sets how the home runs after launch. Clear authority and open items now prevent confusion once guests arrive.", "how_text": "1. Before the meeting, review the handoff packet ARHA shares, including open items, guest instructions and communication paths.\n2. Write down questions about anything that is unclear or that you expected to be different.\n3. Attend the meeting, confirm the operating authority and approval thresholds that apply after go-live, and ask your questions.\n4. Give any correction or direction on items that need a homeowner decision.\n5. Within the deadline, record your takeaways, questions, decisions and the open items carrying into go-live.", "required_output": "Meeting notes and takeaways (includes ready-for-booking notice and carry-over items)", "documentation_note": "Evidence to keep: Retain the reviewed record, the homeowner's questions or analysis and the final written decision. Time: the homeowner enters actual minutes after doing the work; no estimated or prefilled time. Attestation: the homeowner confirms the entry reflects their own time and work for this home.", "lane": "launch", "stage_window": "onboarding_launch", "team_needs_this": false, "lock_rule": "until_linked_step_done", "linked_template_task_ids": [], "opens_text": "Locked until the handoff meeting is scheduled", "output_fields": [{"key": "takeaways", "label": "Takeaways", "type": "text"}, {"key": "questions", "label": "Questions", "type": "text"}], "status": "released", "retired_at": null}$t$::jsonb; BEGIN
  SELECT * INTO r FROM public.ao_library_cards WHERE code = 'A31' FOR UPDATE;
  r := jsonb_populate_record(r, s);
  UPDATE public.ao_library_cards SET title=r.title, what_text=r.what_text, why_text=r.why_text, how_text=r.how_text, required_output=r.required_output,
    documentation_note=r.documentation_note, lane=r.lane, stage_window=r.stage_window, team_needs_this=r.team_needs_this, lock_rule=r.lock_rule,
    linked_template_task_ids=r.linked_template_task_ids, opens_text=r.opens_text, output_fields=r.output_fields, status=r.status, retired_at=r.retired_at,
    version = version + 1, updated_by = '98bd6696-4018-4965-b645-0471c5ae3925', updated_at = now() WHERE code = 'A31' RETURNING * INTO r;
  INSERT INTO public.ao_library_card_history(card_id, version, snapshot, changed_by) VALUES (r.id, r.version, to_jsonb(r), '98bd6696-4018-4965-b645-0471c5ae3925');
END $do$;
DO $do$ DECLARE r public.ao_library_cards; s jsonb := $t${"title": "Review operating statements", "what_text": "ARHA shares operating statements through the agreed homeowner channel and explains any item that needs a homeowner decision. The homeowner reviews the information for the home and asks questions through ARHA.\n\nWhy it matters: Statements show how the home is performing and surface decisions that need you. Questions are best raised while the month is fresh.\n\nSteps:\n1. Open the statement ARHA issued and confirm it is for the correct home and month.\n2. Review revenue, expenses and any maintenance or repair items listed.\n3. Identify any item that needs a homeowner decision, such as a repair approval or a recurring service change.\n4. Write specific questions tied to a line item.\n5. Submit the statement month and your questions or decisions. Reviewing for personal interest alone is not a decision; note the operating action you are taking, if any.\n\nWhat to submit: Statement review with questions. Answer fields: Statement month, question.\n\nWhat to keep: Retain the reviewed record, the homeowner's questions or analysis and the final written decision.\n\nRecord only the time you personally spend on this card. Do not include time spent by ARHA, a vendor or another household member.", "why_text": "Statements show how the home is performing and surface decisions that need you. Questions are best raised while the month is fresh.", "how_text": "1. Open the statement ARHA issued and confirm it is for the correct home and month.\n2. Review revenue, expenses and any maintenance or repair items listed.\n3. Identify any item that needs a homeowner decision, such as a repair approval or a recurring service change.\n4. Write specific questions tied to a line item.\n5. Submit the statement month and your questions or decisions. Reviewing for personal interest alone is not a decision; note the operating action you are taking, if any.", "required_output": "Statement review with questions", "documentation_note": "Evidence to keep: Retain the reviewed record, the homeowner's questions or analysis and the final written decision. Time: the homeowner enters actual minutes after doing the work; no estimated or prefilled time. Attestation: the homeowner confirms the entry reflects their own time and work for this home.", "lane": "triggered", "stage_window": "operations", "team_needs_this": false, "lock_rule": "until_linked_step_done", "linked_template_task_ids": [], "opens_text": "Locked until ARHA issues a statement", "output_fields": [{"key": "statement_month", "label": "Statement month", "type": "text"}, {"key": "question", "label": "Question", "type": "text"}], "status": "released", "retired_at": null}$t$::jsonb; BEGIN
  SELECT * INTO r FROM public.ao_library_cards WHERE code = 'A35' FOR UPDATE;
  r := jsonb_populate_record(r, s);
