    documentation_note=r.documentation_note, lane=r.lane, stage_window=r.stage_window, team_needs_this=r.team_needs_this, lock_rule=r.lock_rule,
    linked_template_task_ids=r.linked_template_task_ids, opens_text=r.opens_text, output_fields=r.output_fields, status=r.status, retired_at=r.retired_at,
    version = version + 1, updated_by = '98bd6696-4018-4965-b645-0471c5ae3925', updated_at = now() WHERE code = 'A35' RETURNING * INTO r;
  INSERT INTO public.ao_library_card_history(card_id, version, snapshot, changed_by) VALUES (r.id, r.version, to_jsonb(r), '98bd6696-4018-4965-b645-0471c5ae3925');
END $do$;
DO $do$ DECLARE r public.ao_library_cards; s jsonb := $t${"title": "Review onboarding costs and invoices", "what_text": "ARHA prepares invoices and supporting cost details. The homeowner reviews the charges for their home and pays through the authorized channel; ARHA tracks approval and payment status.\n\nWhy it matters: Reviewing final onboarding costs confirms every charge matches what you approved before the home goes live.\n\nSteps:\n1. Open the onboarding cost summary ARHA issued.\n2. Compare each line item with the scopes, estimates and invoices you previously approved.\n3. Mark any line item that does not match or needs explanation, and write the question.\n4. Pay through the authorized channel in the service agreement once your questions are answered.\n5. Submit the line items you questioned and the answers you received.\n\nWhat to submit: Cost review with questions. Answer fields: Line item, question.\n\nWhat to keep: Retain the reviewed record, the homeowner's questions or analysis and the final written decision.\n\nRecord only the time you personally spend on this card. Do not include time spent by ARHA, a vendor or another household member.", "why_text": "Reviewing final onboarding costs confirms every charge matches what you approved before the home goes live.", "how_text": "1. Open the onboarding cost summary ARHA issued.\n2. Compare each line item with the scopes, estimates and invoices you previously approved.\n3. Mark any line item that does not match or needs explanation, and write the question.\n4. Pay through the authorized channel in the service agreement once your questions are answered.\n5. Submit the line items you questioned and the answers you received.", "required_output": "Cost review with questions", "documentation_note": "Evidence to keep: Retain the reviewed record, the homeowner's questions or analysis and the final written decision. Time: the homeowner enters actual minutes after doing the work; no estimated or prefilled time. Attestation: the homeowner confirms the entry reflects their own time and work for this home.", "lane": "launch", "stage_window": "onboarding_launch", "team_needs_this": false, "lock_rule": "until_linked_step_done", "linked_template_task_ids": [], "opens_text": "Locked until ARHA issues the cost summary", "output_fields": [{"key": "line_item", "label": "Line item", "type": "text"}, {"key": "question", "label": "Question", "type": "text"}], "status": "released", "retired_at": null}$t$::jsonb; BEGIN
  SELECT * INTO r FROM public.ao_library_cards WHERE code = 'A41' FOR UPDATE;
  r := jsonb_populate_record(r, s);
  UPDATE public.ao_library_cards SET title=r.title, what_text=r.what_text, why_text=r.why_text, how_text=r.how_text, required_output=r.required_output,
    documentation_note=r.documentation_note, lane=r.lane, stage_window=r.stage_window, team_needs_this=r.team_needs_this, lock_rule=r.lock_rule,
    linked_template_task_ids=r.linked_template_task_ids, opens_text=r.opens_text, output_fields=r.output_fields, status=r.status, retired_at=r.retired_at,
    version = version + 1, updated_by = '98bd6696-4018-4965-b645-0471c5ae3925', updated_at = now() WHERE code = 'A41' RETURNING * INTO r;
  INSERT INTO public.ao_library_card_history(card_id, version, snapshot, changed_by) VALUES (r.id, r.version, to_jsonb(r), '98bd6696-4018-4965-b645-0471c5ae3925');
