DO $do$ DECLARE r public.ao_library_cards; s jsonb := $t${"title": "Coordinate a remote third-party home documentation session", "what_text": "ARHA can coordinate access and an onsite representative when available. The homeowner schedules the independent professional, confirms the requested documentation and obtains their own professional advice about the purpose and use of the session.\n\nWhy it matters: Some documentation requires an independent professional and onsite access. Coordinating it early avoids delays.\n\nSteps:\n1. Confirm with your independent professional what the session must document and how long it will take.\n2. Propose two or three session windows to ARHA so access and an onsite representative can be arranged.\n3. Confirm the final date, provider name and access instructions with ARHA.\n4. Join remotely if the provider offers it, and answer the provider's property questions.\n5. Record the provider, session date and notes. ARHA or vendor time at the session is not your time.\n\nWhat to submit: Session confirmation and notes. Answer fields: Provider, date, notes.\n\nWhat to keep: Keep the provider confirmation, the session date and your notes.\n\nRecord only the time you personally spend on this card. Do not include time spent by ARHA, a vendor or another household member.", "why_text": "Some documentation requires an independent professional and onsite access. Coordinating it early avoids delays.", "how_text": "1. Confirm with your independent professional what the session must document and how long it will take.\n2. Propose two or three session windows to ARHA so access and an onsite representative can be arranged.\n3. Confirm the final date, provider name and access instructions with ARHA.\n4. Join remotely if the provider offers it, and answer the provider's property questions.\n5. Record the provider, session date and notes. ARHA or vendor time at the session is not your time.", "required_output": "Session confirmation and notes", "documentation_note": "Evidence to keep: Keep the provider confirmation, the session date and your notes. Time: the homeowner enters actual minutes after doing the work; no estimated or prefilled time. Attestation: the homeowner confirms the entry reflects their own time and work for this home.", "lane": "triggered", "stage_window": "anytime", "team_needs_this": false, "lock_rule": "until_linked_step_done", "linked_template_task_ids": [], "opens_text": "Locked until ARHA schedules the session", "output_fields": [{"key": "provider", "label": "Provider", "type": "text"}, {"key": "date", "label": "Date", "type": "date"}, {"key": "notes", "label": "Notes", "type": "text"}], "status": "released", "retired_at": null}$t$::jsonb; BEGIN
  SELECT * INTO r FROM public.ao_library_cards WHERE code = 'A56' FOR UPDATE;
  r := jsonb_populate_record(r, s);
  UPDATE public.ao_library_cards SET title=r.title, what_text=r.what_text, why_text=r.why_text, how_text=r.how_text, required_output=r.required_output,
    documentation_note=r.documentation_note, lane=r.lane, stage_window=r.stage_window, team_needs_this=r.team_needs_this, lock_rule=r.lock_rule,
    linked_template_task_ids=r.linked_template_task_ids, opens_text=r.opens_text, output_fields=r.output_fields, status=r.status, retired_at=r.retired_at,
    version = version + 1, updated_by = '98bd6696-4018-4965-b645-0471c5ae3925', updated_at = now() WHERE code = 'A56' RETURNING * INTO r;
