END $do$;
DO $do$ DECLARE r public.ao_library_cards; s jsonb := $t${"title": "Document your onboarding planning call", "what_text": "ARHA leads the planning call to confirm the homeowner's goals for the home, explain the onboarding process and record decisions, questions and next steps. The homeowner documents their own participation and confirms the shared understanding.\n\nWhy it matters: The planning call sets goals, timeline and decisions for the whole onboarding. A written record keeps everyone aligned.\n\nSteps:\n1. Before the call, write down your goals for the home, any known issues and the decisions you expect to make.\n2. Attend the call and review the launch plan, timeline and open decisions with ARHA.\n3. Ask questions and confirm the decisions you made during the call.\n4. Within the deadline, record the decisions, open questions and next steps in this card.\n5. Correct anything in ARHA's call summary that does not match your understanding.\n\nWhat to submit: Written takeaways from the call. Answer fields: Decisions, questions, next steps.\n\nWhat to keep: Retain the completed worksheet or draft, source links and any supporting screenshots used to prepare it.\n\nRecord only the time you personally spend on this card. Do not include time spent by ARHA, a vendor or another household member.", "why_text": "The planning call sets goals, timeline and decisions for the whole onboarding. A written record keeps everyone aligned.", "how_text": "1. Before the call, write down your goals for the home, any known issues and the decisions you expect to make.\n2. Attend the call and review the launch plan, timeline and open decisions with ARHA.\n3. Ask questions and confirm the decisions you made during the call.\n4. Within the deadline, record the decisions, open questions and next steps in this card.\n5. Correct anything in ARHA's call summary that does not match your understanding.", "required_output": "Written takeaways from the call", "documentation_note": "Evidence to keep: Retain the completed worksheet or draft, source links and any supporting screenshots used to prepare it. Time: the homeowner enters actual minutes after doing the work; no estimated or prefilled time. Attestation: the homeowner confirms the entry reflects their own time and work for this home.", "lane": "critical", "stage_window": "onboarding_early", "team_needs_this": false, "lock_rule": "until_linked_step_done", "linked_template_task_ids": [], "opens_text": "Locked until the planning call is held", "output_fields": [{"key": "decisions", "label": "Decisions", "type": "text"}, {"key": "questions", "label": "Questions", "type": "text"}, {"key": "next_steps", "label": "Next steps", "type": "text"}], "status": "released", "retired_at": null}$t$::jsonb; BEGIN
  SELECT * INTO r FROM public.ao_library_cards WHERE code = 'A57' FOR UPDATE;
  r := jsonb_populate_record(r, s);
