END $do$;
DO $do$ DECLARE r public.ao_library_cards; s jsonb := $t${"title": "Choose towels, linens and guest supplies", "what_text": "Review the homeowner-safe ARHA linen, bath and guest-supply standard, decide where to use the standard, and propose only the property-specific upgrades or additions that would improve the guest experience.\n\nWhy it matters: Linens and guest supplies are touched in every stay. The right choices protect reviews and keep turnovers consistent.\n\nSteps:\n1. Review the ARHA standard categories against the home's bed sizes, bathrooms, occupancy and planned guest use.\n2. For each category, mark either Use ARHA standard or Propose an upgrade or addition.\n3. Keep all sheets, duvet covers, bath towels, hand towels and washcloths white. Do not propose colored or patterned replacements for those turnover items.\n4. For each proposed upgrade or addition, list the item type, desired quantity, important feature, approximate budget and the guest need it addresses. A public product link may be included when the homeowner is recommending a specific item, but ARHA's internal links are not provided.\n5. Separate an actual guest-use improvement from a design preference so ARHA can evaluate durability, laundering, replacement and cost.\n\nWhat to submit: Decision sheet: use ARHA standard or propose an addition, by category. Answer fields: Category, decision, proposed item, quantity, budget, guest need.\n\nWhat to keep: Retain the reviewed record, the homeowner's questions or analysis and the final written decision.\n\nRecord only the time you personally spend on this card. Do not include time spent by ARHA, a vendor or another household member.", "why_text": "Linens and guest supplies are touched in every stay. The right choices protect reviews and keep turnovers consistent.", "how_text": "1. Review the ARHA standard categories against the home's bed sizes, bathrooms, occupancy and planned guest use.\n2. For each category, mark either Use ARHA standard or Propose an upgrade or addition.\n3. Keep all sheets, duvet covers, bath towels, hand towels and washcloths white. Do not propose colored or patterned replacements for those turnover items.\n4. For each proposed upgrade or addition, list the item type, desired quantity, important feature, approximate budget and the guest need it addresses. A public product link may be included when the homeowner is recommending a specific item, but ARHA's internal links are not provided.\n5. Separate an actual guest-use improvement from a design preference so ARHA can evaluate durability, laundering, replacement and cost.", "required_output": "Decision sheet: use ARHA standard or propose an addition, by category", "documentation_note": "Evidence to keep: Retain the reviewed record, the homeowner's questions or analysis and the final written decision. Time: the homeowner enters actual minutes after doing the work; no estimated or prefilled time. Attestation: the homeowner confirms the entry reflects their own time and work for this home.", "lane": "critical", "stage_window": "onboarding_early", "team_needs_this": true, "lock_rule": "until_linked_step_done", "linked_template_task_ids": [], "opens_text": "Locked until ARHA shares bed sizes and occupancy", "output_fields": [{"key": "category", "label": "Category", "type": "text"}, {"key": "decision", "label": "Decision", "type": "text"}, {"key": "proposed_item", "label": "Proposed item", "type": "text"}, {"key": "quantity", "label": "Quantity", "type": "number"}, {"key": "budget", "label": "Budget", "type": "money_text"}, {"key": "guest_need", "label": "Guest need", "type": "text"}], "status": "released", "retired_at": null}$t$::jsonb; BEGIN
  SELECT * INTO r FROM public.ao_library_cards WHERE code = 'P03' FOR UPDATE;
  r := jsonb_populate_record(r, s);
  UPDATE public.ao_library_cards SET title=r.title, what_text=r.what_text, why_text=r.why_text, how_text=r.how_text, required_output=r.required_output,
    documentation_note=r.documentation_note, lane=r.lane, stage_window=r.stage_window, team_needs_this=r.team_needs_this, lock_rule=r.lock_rule,
