DO $do$ DECLARE r public.ao_library_cards; s jsonb := $t${"title": "Choose kitchen and household items", "what_text": "Review the homeowner-safe ARHA kitchen and household standard, choose where to use the standard, and recommend only additions that solve a property-specific guest need.\n\nWhy it matters: Kitchen and household items decide whether guests can actually live in the home for weeks. Real gaps matter more than extras.\n\nSteps:\n1. Review the ARHA standard categories against the home's occupancy, kitchen layout, storage, guest segments and any confirmed special use.\n2. For each category, mark either Use ARHA standard or Propose an upgrade or addition.\n3. Do not attempt to recreate ARHA's complete inventory, sourcing or design system. Focus on real gaps or guest-use additions specific to this home.\n4. For each proposed addition, provide the item type, quantity, intended function, approximate budget, storage or cleaning consideration and the guest need it addresses.\n5. A public product link may be included when the homeowner is proposing a specific item. ARHA will evaluate compatibility, durability, cleaning requirements, warranty, availability and replacement ease through its normal process.\n6. Rank each proposed addition as must-have, helpful or optional so ARHA can evaluate it against the approved budget.\n\nWhat to submit: Prioritized decision sheet of proposed additions. Answer fields: Category, decision, item, quantity, function, budget, priority.\n\nWhat to keep: Retain the reviewed record, the homeowner's questions or analysis and the final written decision.\n\nRecord only the time you personally spend on this card. Do not include time spent by ARHA, a vendor or another household member.", "why_text": "Kitchen and household items decide whether guests can actually live in the home for weeks. Real gaps matter more than extras.", "how_text": "1. Review the ARHA standard categories against the home's occupancy, kitchen layout, storage, guest segments and any confirmed special use.\n2. For each category, mark either Use ARHA standard or Propose an upgrade or addition.\n3. Do not attempt to recreate ARHA's complete inventory, sourcing or design system. Focus on real gaps or guest-use additions specific to this home.\n4. For each proposed addition, provide the item type, quantity, intended function, approximate budget, storage or cleaning consideration and the guest need it addresses.\n5. A public product link may be included when the homeowner is proposing a specific item. ARHA will evaluate compatibility, durability, cleaning requirements, warranty, availability and replacement ease through its normal process.\n6. Rank each proposed addition as must-have, helpful or optional so ARHA can evaluate it against the approved budget.", "required_output": "Prioritized decision sheet of proposed additions", "documentation_note": "Evidence to keep: Retain the reviewed record, the homeowner's questions or analysis and the final written decision. Time: the homeowner enters actual minutes after doing the work; no estimated or prefilled time. Attestation: the homeowner confirms the entry reflects their own time and work for this home.", "lane": "critical", "stage_window": "onboarding_early", "team_needs_this": true, "lock_rule": "until_linked_step_done", "linked_template_task_ids": [], "opens_text": "Locked until ARHA shares occupancy and layout details", "output_fields": [{"key": "category", "label": "Category", "type": "text"}, {"key": "decision", "label": "Decision", "type": "text"}, {"key": "item", "label": "Item", "type": "text"}, {"key": "quantity", "label": "Quantity", "type": "number"}, {"key": "function", "label": "Function", "type": "text"}, {"key": "budget", "label": "Budget", "type": "money_text"}, {"key": "priority", "label": "Priority", "type": "text"}], "status": "released", "retired_at": null}$t$::jsonb; BEGIN
  SELECT * INTO r FROM public.ao_library_cards WHERE code = 'P04' FOR UPDATE;
  r := jsonb_populate_record(r, s);
  UPDATE public.ao_library_cards SET title=r.title, what_text=r.what_text, why_text=r.why_text, how_text=r.how_text, required_output=r.required_output,
    documentation_note=r.documentation_note, lane=r.lane, stage_window=r.stage_window, team_needs_this=r.team_needs_this, lock_rule=r.lock_rule,
    linked_template_task_ids=r.linked_template_task_ids, opens_text=r.opens_text, output_fields=r.output_fields, status=r.status, retired_at=r.retired_at,
    version = version + 1, updated_by = '98bd6696-4018-4965-b645-0471c5ae3925', updated_at = now() WHERE code = 'P04' RETURNING * INTO r;
  INSERT INTO public.ao_library_card_history(card_id, version, snapshot, changed_by) VALUES (r.id, r.version, to_jsonb(r), '98bd6696-4018-4965-b645-0471c5ae3925');
