DO $do$ DECLARE r public.ao_library_cards; s jsonb := $t${"title": "Draft an Instagram launch campaign", "what_text": "Create a six-piece Instagram campaign using feed, story or short-video concepts that communicate the home's real features and local usefulness.\n\nWhy it matters: Instagram shows the home visually and can reach local and professional audiences who refer guests.\n\nSteps:\n1. Create six concepts covering the property introduction, design or comfort, a key amenity, the local area, an intended stay use and a referral reminder.\n2. Write the caption, on-image text if any, asset direction, accessibility description, call to action and suggested posting date for each concept.\n3. Create a concise set of relevant location and property tags without using misleading claims.\n4. Identify which concepts can use existing MLS or design material and which need final ARHA photos.\n5. Finalize the package with ARHA-approved facts, photos and listing link.\n\nWhat to submit: Six-post campaign. Answer fields: Post text, photo choice, date.\n\nWhat to keep: Retain the completed worksheet or draft, source links and any supporting screenshots used to prepare it.\n\nRecord only the time you personally spend on this card. Do not include time spent by ARHA, a vendor or another household member.", "why_text": "Instagram shows the home visually and can reach local and professional audiences who refer guests.", "how_text": "1. Create six concepts covering the property introduction, design or comfort, a key amenity, the local area, an intended stay use and a referral reminder.\n2. Write the caption, on-image text if any, asset direction, accessibility description, call to action and suggested posting date for each concept.\n3. Create a concise set of relevant location and property tags without using misleading claims.\n4. Identify which concepts can use existing MLS or design material and which need final ARHA photos.\n5. Finalize the package with ARHA-approved facts, photos and listing link.", "required_output": "Six-post campaign", "documentation_note": "Evidence to keep: Retain the completed worksheet or draft, source links and any supporting screenshots used to prepare it. Time: the homeowner enters actual minutes after doing the work; no estimated or prefilled time. Attestation: the homeowner confirms the entry reflects their own time and work for this home.", "lane": "launch", "stage_window": "onboarding_launch", "team_needs_this": false, "lock_rule": "none", "linked_template_task_ids": [], "opens_text": "Draft open on day one; final step unlocks when ARHA shares approved photos and link", "output_fields": [{"key": "post_text", "label": "Post text", "type": "text"}, {"key": "photo_choice", "label": "Photo choice", "type": "text"}, {"key": "date", "label": "Date", "type": "date"}], "status": "released", "retired_at": null}$t$::jsonb; BEGIN
