DO $do$ DECLARE r public.ao_library_cards; s jsonb := $t${"title": "Prepare messages for friends, family and colleagues", "what_text": "Prepare personal, human outreach that lets the homeowner's existing network know about the furnished home and how to refer an appropriate guest.\n\nWhy it matters: Personal outreach from you is one of the most trusted ways a furnished home gets its first referrals.\n\nSteps:\n1. Divide the homeowner's existing network into family and friends, professional contacts and community contacts.\n2. Draft one short text, one group-message version, one email and one follow-up message using the homeowner's natural voice.\n3. Explain the type of stay the home may support without promising a rate, date or booking.\n4. Include the ARHA-approved link or inquiry route and a clear request to share it with someone who may need furnished housing.\n5. Finalize the messages when the live link is available and record only outreach the homeowner actually sends.\n\nWhat to submit: Text and email message set. Answer fields: Audience, channel, message.\n\nWhat to keep: Keep the final message set and a record of the outreach you actually sent.\n\nRecord only the time you personally spend on this card. Do not include time spent by ARHA, a vendor or another household member.", "why_text": "Personal outreach from you is one of the most trusted ways a furnished home gets its first referrals.", "how_text": "1. Divide the homeowner's existing network into family and friends, professional contacts and community contacts.\n2. Draft one short text, one group-message version, one email and one follow-up message using the homeowner's natural voice.\n3. Explain the type of stay the home may support without promising a rate, date or booking.\n4. Include the ARHA-approved link or inquiry route and a clear request to share it with someone who may need furnished housing.\n5. Finalize the messages when the live link is available and record only outreach the homeowner actually sends.", "required_output": "Text and email message set", "documentation_note": "Evidence to keep: Keep the final message set and a record of the outreach you actually sent. Time: the homeowner enters actual minutes after doing the work; no estimated or prefilled time. Attestation: the homeowner confirms the entry reflects their own time and work for this home.", "lane": "launch", "stage_window": "onboarding_launch", "team_needs_this": false, "lock_rule": "none", "linked_template_task_ids": [], "opens_text": "Draft open on day one; final step unlocks when ARHA shares the live link", "output_fields": [{"key": "audience", "label": "Audience", "type": "text"}, {"key": "channel", "label": "Channel", "type": "text"}, {"key": "message", "label": "Message", "type": "text"}], "status": "released", "retired_at": null}$t$::jsonb; BEGIN
